function validate([sentence]) {
  if (typeof sentence !== 'string') return 'sentence must be a string.';
  if (sentence.length < 1 || sentence.length > 1000) return 'sentence needs 1 to 1000 letters.';
  if (!/^[a-z]+$/.test(sentence)) return 'sentence may contain only lowercase English letters.';
  return null;
}

