function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const pick = (letters) => letters[Math.floor(rand() * letters.length)];
  const mode = rand();
  if (size === 'small') {
    if (mode < 0.4) {
      // A shuffled full alphabet, sometimes with one letter removed.
      const letters = alphabet.split('');
      for (let i = letters.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [letters[i], letters[j]] = [letters[j], letters[i]];
      }
      if (rand() < 0.5) letters.pop();
      const extra = Math.floor(rand() * 6);
      for (let i = 0; i < extra; i++) letters.splice(Math.floor(rand() * (letters.length + 1)), 0, pick(alphabet));
      return [letters.join('')];
    }
    const pool = alphabet.slice(0, 1 + Math.floor(rand() * 26));
    const n = 1 + Math.floor(rand() * 40);
    let s = '';
    for (let i = 0; i < n; i++) s += pick(pool);
    return [s];
  }
  // Large: 1000 letters, missing one letter about half the time.
  const pool = mode < 0.5 ? alphabet.replace(pick(alphabet), '') : alphabet;
  let s = '';
  for (let i = 0; i < 1000; i++) s += pick(pool);
  return [s];
}
